import{z as n,x as h,o as e,c as f,q as r,j as m,D as t,d as i,s,S as C,b as o}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"Hopkins TCC","description":"","frontmatter":{"title":"Hopkins TCC","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/hopkins-tcc.md","filePath":"litho/hopkins-tcc.md","lastUpdated":1791413859000}'),l={name:"litho/hopkins-tcc.md"};function p(A,a,B,d,T,b){const E=h("Mermaid");return e(),f("div",null,[a[2]||(a[2]=r('<h1 id="hopkins-tcc" tabindex="-1">Hopkins TCC <a class="header-anchor" href="#hopkins-tcc" aria-label="Permalink to &quot;Hopkins TCC&quot;">​</a></h1><div class="epigraph"><p>部分相干强度对物体是双线性的；传递交叉系数把光源与光瞳的重叠先算死，掩模只进一对频率。</p><footer>—— H. H. Hopkins, On the diffraction theory of optical images, Proc. R. Soc. Lond. A (1953)</footer></div><p><a href="/litho/coherence-sigma">上一课</a>把有效光源钉在单位光瞳上，支撑由 \\(\\sigma\\)（或环带内外径）划定。缺口是：若对每个源点各做一次相干成像再加强度，掩模一改就要重扫整个源。Hopkins 把顺序换成：先把源与两个错位光瞳收成四维核 \\(\\mathrm{TCC}(\\mathbf{f}_1,\\mathbf{f}_2)\\)，强度对物频谱双线性。空中像对比怎么读，留给<a href="/litho/aerial-image-contrast">空中像与对比度</a>。本课不从瑞利判据重讲分辨率。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>上一课的源点叠加在概念上已经完备，计算上却把照明与物体缠在一起。工艺上照明、镜头几天不变，版图每个层次都变。缺口因此是一个<strong>与掩模无关</strong>的核：照明形状和光瞳函数进 TCC，物体只通过频谱的一对频率进来。没有这个核，后课的 OPC 无法把「光学算子」从多边形循环里提出来。</p><p><span class="marginnote">术语翻译：「与掩模无关的核」就是光学系统自带的一张价格表——不管版图怎么改，光源和镜头决定每对频率能传多少，查表即可；只有换光源或镜头，这张表才要重做。OPC 改几十万个多边形，改的从来不是表本身。</span></p><p>完全相干是退化：TCC 变成光瞳的乘积 \\(P(\\mathbf{f}_1)P^*(\\mathbf{f}_2)\\)。完全非相干则 TCC 只依赖差频，成为光瞳的自相关。产线落在中间，必须保留完整的四维函数。</p><p><span class="marginnote">数字实例：同一台 NA 0.33、\\(\\lambda=13.5\\) nm 的机器，完全相干（\\(\\sigma\\to 0\\)）最高传 \\(\\mathrm{NA}/\\lambda\\approx 24\\) /µm，对应最小周期约 41 nm；完全非相干（\\(\\sigma=1\\)）能传到 \\(2\\mathrm{NA}/\\lambda\\approx 49\\) /µm，周期缩到约 20 nm。产线的 \\(\\sigma\\) 就是在这两端之间挑工作点。</span></p><h3 id="四维不是装饰" tabindex="-1">四维不是装饰 <a class="header-anchor" href="#四维不是装饰" aria-label="Permalink to &quot;四维不是装饰&quot;">​</a></h3><p>物频谱 \\(T(\\mathbf{f})\\) 是二维的；强度涉及 \\(T(\\mathbf{f}_1)T^*(\\mathbf{f}_2)\\)，自变量是一对二维频率，故 TCC 是四维。不要把它画成「又一条 MTF 曲线」。MTF 是非相干或单频对比的切片；TCC 才是部分相干的完整核。</p><p><span class="marginnote">Hopkins 的有效光源 \\(S(\\mathbf{f})\\) 就是上一课的光瞳填充。圆、环、四极全部进 \\(S\\)，不进掩模。换照明 = 换 TCC，旧光学模型作废。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>标量形式（频率归一到像方 \\(\\mathrm{NA}/\\lambda\\)）写</p> \\[\\mathrm{TCC}(\\mathbf{f}_1,\\mathbf{f}_2)=\\iint S(\\mathbf{f})\\,P(\\mathbf{f}+\\mathbf{f}_1)\\,P^*(\\mathbf{f}+\\mathbf{f}_2)\\,d^2\\mathbf{f}. \\]<p>几何上：把投影光瞳复制两份，分别平移到 \\(-\\mathbf{f}_1\\)、\\(-\\mathbf{f}_2\\)，与光源重叠的那块面积（再计光瞳复相位）就是该频率对的传递。空中像</p> \\[I(\\mathbf{x})=\\iint T(\\mathbf{f}_1)T^*(\\mathbf{f}_2)\\,\\mathrm{TCC}(\\mathbf{f}_1,\\mathbf{f}_2)\\,e^{2\\pi i(\\mathbf{f}_1-\\mathbf{f}_2)\\cdot\\mathbf{x}}\\,d^2\\mathbf{f}_1\\,d^2\\mathbf{f}_2. \\]<p>这就是双线性：对 \\(T\\) 不是线性滤波。相干像场的 \\(|U|^2\\) 展开后，交叉项正是这对频率。</p><h3 id="本征展开只是算法" tabindex="-1">本征展开只是算法 <a class="header-anchor" href="#本征展开只是算法" aria-label="Permalink to &quot;本征展开只是算法&quot;">​</a></h3><p>把 TCC 看成对 \\((\\mathbf{f}_1,\\mathbf{f}_2)\\) 的核，做本征分解（SOCS 一类），强度变成少数相干核的平方和。本课不讲数值秩、不讲 GPU。只承认：四维核是确定的物理对象，计算上可以压成几个相干通道，而不改变 Hopkins 的定义。</p><p><span class="marginnote">离焦与像差进 \\(P\\) 的相位，因而进 TCC，不进 \\(S\\)。\\(\\sigma\\) 改 \\(S\\) 的支撑。两个旋钮在公式里位置不同，不能互相替代。</span></p>',20)),(e(),m(C,null,{default:t(()=>[s(E,{id:"mermaid-54",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E6%9C%89%E6%95%88%E5%85%89%E6%BA%90%20S%22%5D%20--%3E%20TCC%5B%22TCC(f1%2C%20f2)%22%5D%0A%20%20P%5B%22%E5%85%89%E7%9E%B3%20P%22%5D%20--%3E%20TCC%0A%20%20T%5B%22%E7%89%A9%E9%A2%91%E8%B0%B1%20T%22%5D%20--%3E%20I%5B%22%E7%A9%BA%E4%B8%AD%E5%83%8F%20I%22%5D%0A%20%20TCC%20--%3E%20I%0A%20%20I%20--%3E%20NEXT%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%AF%B9%E6%AF%94%E5%BA%A6%20%2F%20NILS%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o("h2",{id:"机制",tabindex:"-1"},[i("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=o("p",null,"某一对频率能否对强度有贡献，看平移后的两个光瞳与光源有没有交集。密图形对应大的 \\(|\\mathbf{f}|\\)，平移大，重叠变瘦，TCC 变小——这就是部分相干下「高频掉对比」的积分图像，不必先画艾里斑。源拉成环，重叠区域搬家，某些节距的 TCC 升、另一些降：RET 改照明的全部机制已经写在这个重叠里。",-1)),(e(),m(C,null,{default:t(()=>[s(E,{id:"mermaid-61",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22TCC%20%E5%AF%B9%E6%9F%90%E5%AF%B9%E9%A2%91%E7%8E%87%E7%BB%99%E5%87%BA%E5%A4%9A%E5%B0%91%E6%9D%83%E9%87%8D%EF%BC%9F%22%5D%20--%3E%20A%5B%22%E5%85%89%E6%BA%90%E5%9C%86%E7%89%87%20S%22%5D%0A%20%20Q%20--%3E%20B%5B%22%E5%85%89%E7%9E%B3%E5%9C%86%E7%89%87%E5%B9%B3%E7%A7%BB%20-f1%22%5D%0A%20%20Q%20--%3E%20C%5B%22%E5%85%89%E7%9E%B3%E5%9C%86%E7%89%87%E5%B9%B3%E7%A7%BB%20-f2%22%5D%0A%20%20A%20--%3E%20O%5B%22%E4%B8%89%E8%80%85%E7%9A%84%E5%85%AC%E5%85%B1%E4%BA%A4%E9%9B%86%22%5D%0A%20%20B%20--%3E%20O%0A%20%20C%20--%3E%20O%0A%20%20O%20--%3E%20T1%5B%22%7Cf%7C%20%E5%B0%8F%EF%BC%9A%E4%BA%A4%E9%9B%86%E8%83%96%EF%BC%8CTCC%20%E5%A4%A7%22%5D%0A%20%20O%20--%3E%20T2%5B%22%7Cf%7C%20%E5%A4%A7%EF%BC%9A%E4%BA%A4%E9%9B%86%E7%98%A6%E6%88%90%E6%9C%88%E7%89%99%EF%BC%8CTCC%20%E5%B0%8F%22%5D%0A%20%20O%20--%3E%20T3%5B%22%E6%B2%A1%E6%9C%89%E4%BA%A4%E9%9B%86%EF%BC%9ATCC%20%3D%200%EF%BC%8C%E8%AF%A5%E9%A2%91%E7%8E%87%E4%BC%A0%E4%B8%8D%E8%BF%87%E5%8E%BB%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=r('<p><span class="marginnote">直觉类比：把光源和光瞳想成三张圆纸片，两张瞳片各朝相反方向挪动。挪得越远（频率差越大），三张纸片的公共交集就从大圆缩成月牙、再到完全没有——交集面积就是这对频率传到像面的权重。</span></p><p>双线性意味着邻域：一点的强度依赖周围开口的交叉项，光学直径由 TCC 的频率宽度决定。后课 OPC 修边，修的就是这套交叉项，不是本地偏置。</p><h3 id="后课默认的接口" tabindex="-1">后课默认的接口 <a class="header-anchor" href="#后课默认的接口" aria-label="Permalink to &quot;后课默认的接口&quot;">​</a></h3><p>说到部分相干成像，默认强度由 TCC 双线性给出；\\(S\\) 由 \\(\\sigma\\) 与光瞳图案决定，\\(P\\) 含 \\(\\mathrm{NA}\\)、离焦与像差。空中像课只读 \\(I(\\mathbf{x})\\) 的对比，不再把源点循环重讲一遍。矢量 TCC 把 \\(P\\) 换成偏振通道，定义结构相同，那是高 \\(\\mathrm{NA}\\) 课的缺口。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>1953 年的标量 Hopkins 不含掩模厚度、不含胶内矢量沉积。TCC 对固定照明与镜头是常数，对扫描狭缝场点可以变（镜头指纹），那是场相关模型，不是新原理。也不要把 TCC 叫做「相干因子」：\\(\\sigma\\) 是 \\(S\\) 的半径，TCC 是重叠积分。</p><p>本课不引用未公开的 OPC 引擎截断秩。后课需要的只是：核存在、与掩模分离、对 \\(T\\) 双线性。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>TCC 是源与两个错位光瞳的重叠，四维，掩模无关。</li><li>空中像对物频谱双线性；相干 / 非相干是两种退化。</li><li>换 \\(\\sigma\\) 或光瞳图案 = 换 TCC；离焦进 \\(P\\) 也改 TCC。</li><li>本征分解是计算，不是新的成像理论。</li><li>下一课从 \\(I(\\mathbf{x})\\) 读对比度。</li><li>出处：Hopkins (1953), <em>Proc. R. Soc. Lond. A</em>；产线用法见 Mack。</li></ul>',9))])}const P=n(l,[["render",p]]);export{_ as __pageData,P as default};
